package com.stuassistant.app.nativeapp

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.TimeZone

/** Expected results are generated by the real JS modules; see web/tests/generate-native-academic-fixture.cjs. */
class NativeAcademicDomainTest {
    private val fixture: JSONObject by lazy {
        val stream = javaClass.classLoader!!.getResourceAsStream("native-academic-js-parity.json")
        assertNotNull("JS parity fixture missing", stream)
        stream!!.bufferedReader(Charsets.UTF_8).use { JSONObject(it.readText()) }
    }
    private fun objects(key: String) = academicObjects(fixture.getJSONArray(key))
    private fun json(vararg pairs: Pair<String, Any?>) = JSONObject().apply { pairs.forEach { (key, value) -> put(key, value ?: JSONObject.NULL) } }
    private fun equalJson(expected: Any?, actual: Any?, path: String = "root") {
        when (expected) {
            null, JSONObject.NULL -> assertTrue("$path expected null, got $actual", actual == null || actual === JSONObject.NULL)
            is JSONObject -> {
                assertTrue("$path expected object", actual is JSONObject)
                val got = actual as JSONObject
                assertEquals("$path keys", expected.keys().asSequence().toSet(), got.keys().asSequence().toSet())
                expected.keys().forEach { key -> equalJson(expected.opt(key), got.opt(key), "$path.$key") }
            }
            is JSONArray -> {
                assertTrue("$path expected array", actual is JSONArray)
                val got = actual as JSONArray
                assertEquals("$path length", expected.length(), got.length())
                for (i in 0 until expected.length()) equalJson(expected.opt(i), got.opt(i), "$path[$i]")
            }
            is Number -> { assertTrue("$path expected number, got $actual", actual is Number); assertEquals(path, expected.toDouble(), (actual as Number).toDouble(), .0000001) }
            else -> assertEquals(path, expected, actual)
        }
    }

    @Test fun shanghaiClockAndSchoolDeadlinesIgnoreDeviceTimezone() {
        val before = TimeZone.getDefault()
        try {
            for (zone in listOf("UTC", "America/Chicago", "Asia/Shanghai")) {
                TimeZone.setDefault(TimeZone.getTimeZone(zone))
                objects("clock").forEach { row ->
                    val moment = AcademicClock.moment(AcademicClock.parseTime(row.getString("input"))!!)
                    val expected = row.getJSONObject("expected")
                    equalJson(expected, json("ms" to moment.ms, "date" to moment.date, "weekday" to moment.weekday, "minutes" to moment.minutes), zone)
                }
                objects("tasks").forEachIndexed { index, row ->
                    val task = AcademicRecords.task(row.getJSONObject("input"))
                    equalJson(row.getJSONObject("expected"), json("id" to task.id, "title" to task.title, "course" to task.course, "source" to task.source,
                        "url" to task.url, "dueMs" to task.dueMs, "dueRaw" to task.dueRaw, "schoolStatus" to task.schoolStatus), "$zone task[$index]")
                    assertEquals("task[$index] bucket", row.getString("bucket"), AcademicRecords.bucket(task, fixture.getLong("now")))
                }
            }
        } finally { TimeZone.setDefault(before) }
    }

    @Test fun classBlocksMerge100And155MinutesButKeepMealsRoomsAndOverlap() {
        val data = fixture.getJSONObject("timetable")
        val doc = AcademicTimetable.normalize(data.getJSONObject("input"))!!
        val blocks = AcademicTimetable.blocksOn(doc, 8, 3)
        equalJson(data.getJSONArray("blocks"), JSONArray(blocks.map { b -> json("key" to b.key, "periods" to JSONArray(b.periods), "start" to b.start,
            "end" to b.end, "span" to b.span, "location" to b.location, "inferred" to b.inferred, "conflict" to b.conflict) }))
        assertTrue("100-minute first big section", blocks.any { it.course.id == "a" && it.span == 100 })
        assertTrue("155-minute second big section", blocks.any { it.course.id == "b" && it.span == 155 })
        assertEquals("Lunch gap splits same course", 2, blocks.count { it.course.id == "c" })
        assertEquals("Dinner gap splits same course", 2, blocks.count { it.course.id == "d" })
        assertEquals("Rooms remain separate", 2, blocks.count { it.course.id == "e" })
        assertEquals("Fractional and unknown periods discarded", listOf(13), doc.courses.last().meetings.single().periods)
        equalJson(data.getJSONArray("gaps"), JSONArray(AcademicTimetable.gaps(blocks).map { g -> json("start" to g.start, "end" to g.end, "startMin" to g.startMin, "endMin" to g.endMin, "span" to g.span, "label" to g.label) }))
    }

    @Test fun courseDetailPreservesRawFieldsAndCountsClassDays() {
        val data = fixture.getJSONObject("timetable")
        val doc = AcademicTimetable.normalize(data.getJSONObject("input"))!!
        equalJson(data.getJSONArray("slots"), JSONArray(AcademicTimetable.slots(doc.courses.last()).map { slot ->
            json("weekday" to slot.weekday, "periods" to JSONArray(slot.periods), "location" to slot.location, "teacher" to slot.teacher,
                "weeks" to JSONArray(slot.weeks), "rawTimes" to JSONArray(slot.rawTimes), "notes" to JSONArray(slot.notes), "online" to JSONArray(slot.online))
        }))
        val (done, total) = AcademicTimetable.progress(doc.courses.first(), 8, 3, 600)
        equalJson(data.getJSONObject("progress"), json("done" to done, "total" to total))
        val imported = AcademicTimetable.normalize(JSONObject("""{"courses":[{"title":"课程","class_name":"课程班","meetings":[{"weekday":3,"weeks":[8],"periods":[1],"title":"原始教学名称","class_name":"原始教学班"},{"weekday":4,"weeks":[8],"periods":[2]}]}]}"""))!!.courses.single()
        assertEquals("原始教学名称", imported.meetings.first().title)
        assertEquals("原始教学班", imported.meetings.first().className)
        assertEquals("课程", imported.meetings.last().title)
        assertEquals("课程班", imported.meetings.last().className)
    }

    @Test fun calendarClosuresAndUnknownMakeupDoNotInventClasses() {
        val doc = AcademicTimetable.normalize(fixture.getJSONObject("timetable").getJSONObject("input"))!!
        objects("calendar").forEach { row ->
            val date = row.getString("date")
            val status = AcademicCalendar.status(date)
            val output = json("kind" to status.kind)
            if (status.label.isNotEmpty()) output.put("label", status.label)
            if (status.note.isNotEmpty()) output.put("note", status.note)
            if (status.closure.isNotEmpty()) output.put("closure", status.closure)
            equalJson(row.getJSONObject("status"), output, date)
            equalJson(row.opt("week"), AcademicCalendar.position(date)?.week, "$date week")
            assertEquals("$date class count", row.getInt("blocks"), AcademicTimetable.planFor(doc, date).blocks.size)
        }
        equalJson(fixture.getJSONArray("milestones"), JSONArray(AcademicCalendar.milestones("2026-10-28", 4).map { m -> json("label" to m.label, "from" to m.from, "to" to m.to, "days" to m.days, "kind" to m.kind) }))
    }

    @Test fun nonNumericScoresAndGpaUseIndependentCreditDenominators() {
        val data = fixture.getJSONObject("grades")
        val summary = AcademicRecords.summarize(academicObjects(data.getJSONArray("input")).map(AcademicRecords::grade))
        equalJson(data.getJSONObject("expected"), json("weightedScore" to summary.weightedScore, "weightedGpa" to summary.weightedGpa,
            "credits" to summary.credits, "countedCredits" to summary.countedCredits, "counted" to summary.counted, "total" to summary.total))
        assertEquals("25–26 秋", AcademicRecords.semesterLabel("2025-2026-1"))
        assertEquals("25–26 夏", AcademicRecords.semesterLabel("2025-2026-3"))
        assertEquals("原始学期", AcademicRecords.semesterLabel("原始学期"))
    }

    @Test fun examRawTextAndUnknownDatesRemainVisible() {
        objects("exams").forEach { row ->
            val exam = AcademicRecords.exam(row.getJSONObject("input"))
            equalJson(row.getJSONObject("expected"), json("id" to exam.id, "title" to exam.title, "timeRaw" to exam.timeRaw,
                "location" to exam.location, "seat" to exam.seat, "campus" to exam.campus, "notes" to exam.notes, "date" to exam.date, "startMs" to exam.startMs))
        }
    }
}
